# Supporting robot pet classes from the earlier exercises in this chapter.


class RobotPet:
    def __init__(self, name, battery, mood):
        self.name = name
        self.battery = battery
        self.mood = mood

    def show_talent(self):
        return f"{self.name} stands very still."


class RobotCat(RobotPet):
    def show_talent(self):
        return f"{self.name} purrs and chases a laser dot."


class RobotBird(RobotPet):
    def show_talent(self):
        if self.battery == 0:
            return f"{self.name} is out of battery and cannot sing."
        return f"{self.name} sings a bright little tune."


class RobotDog(RobotPet):
    def show_talent(self):
        return f"{self.name} fetches the ball and rolls over."


if __name__ == "__main__":
    import glob
    import os

    here = os.path.dirname(os.path.abspath(__file__))
    for path in sorted(glob.glob(os.path.join(here, "*.py"))):
        if os.path.abspath(path) == os.path.abspath(__file__):
            continue
        with open(path) as source:
            exec(compile(source.read(), path, "exec"), globals())
